const items = $input.all();

return items.map(function (item, index) {
  const text = item.json.content && item.json.content.parts && item.json.content.parts[0] ? item.json.content.parts[0].text : undefined;

  if (typeof text !== 'string' || text.trim() === '') {
    throw new Error(
      'Item ' + (index + 1) + ': No text found in content.parts[0].text'
    );
  }

  // Remove optional JSON or plain code fences.
  const fence = String.fromCharCode(96).repeat(3);
  let cleanedText = text.trim();

  if (cleanedText.startsWith(fence)) {
    cleanedText = cleanedText.slice(3);
    cleanedText = cleanedText.replace(/^json\s*/i, '');
  }

  if (cleanedText.endsWith(fence)) {
    cleanedText = cleanedText.slice(0, -3);
  }

  cleanedText = cleanedText.trim();

  let parsedData;

  try {
    parsedData = JSON.parse(cleanedText);
  } catch (error) {
    throw new Error(
      'Item ' + (index + 1) + ': Failed to parse JSON: ' + error.message
    );
  }

  // Each output item's json must contain an object.
  if (
    parsedData === null ||
    typeof parsedData !== 'object' ||
    Array.isArray(parsedData)
  ) {
    throw new Error(
      'Item ' + (index + 1) + ': Expected a JSON object'
    );
  }

  return {
    json: parsedData,
    pairedItem: {
      item: index
    }
  };
});

const ai = $json;

// Get original Gmail information.
// The node must be named exactly "Gmail Trigger".
const gmail = $('Gmail Trigger').item.json;

function asText(value) {
  return value == null ? '' : String(value).trim();
}

function asNumber(value, defaultValue = 0) {
  if (
    value == null ||
    String(value).trim() === ''
  ) {
    return defaultValue;
  }

  if (
    typeof value !== 'number' &&
    typeof value !== 'string'
  ) {
    return NaN;
  }

  const cleaned = String(value)
    .trim()
    .replace(/,/g, '')
    .replace(/[₹$€£]/g, '')
    .trim();

  return cleaned === '' ? NaN : Number(cleaned);
}

// Validate a receipt date in YYYY-MM-DD format.
function isValidReceiptDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return false;
  }

  const date = new Date(value + 'T00:00:00Z');

  return (
    Number.isFinite(date.getTime()) &&
    date.toISOString().slice(0, 10) === value
  );
}

// Employee from AI, falling back to Gmail sender.
const senderEmail = asText(
  gmail.from && gmail.from.value && gmail.from.value[0] ? gmail.from.value[0].address : ''
);

const employee = asText(ai.employee) || senderEmail;

const vendor = asText(ai.vendor);
const receiptDate = asText(ai.date);

const parsedAmount = asNumber(ai.amount);
const parsedTax = asNumber(ai.tax);
const parsedConfidence = asNumber(ai.confidence);

const expenseLimit = 500;

const allowedCategories = [
  'Travel',
  'Hotel',
  'Food',
  'Transportation',
  'Office Supplies',
  'Software',
  'Entertainment',
  'Medical',
  'Other'
];

const allowedPaymentMethods = [
  'Cash',
  'Credit Card',
  'Debit Card',
  'UPI',
  'Bank Transfer',
  'Other'
];

const errors = [];

if (!vendor) {
  errors.push('Vendor is missing');
}

if (!receiptDate) {
  errors.push('Receipt date is missing');
} else if (!isValidReceiptDate(receiptDate)) {
  errors.push(
    'Invalid receipt date; expected YYYY-MM-DD'
  );
}

if (
  !Number.isFinite(parsedAmount) ||
  parsedAmount <= 0
) {
  errors.push('Invalid expense amount');
}

if (
  !Number.isFinite(parsedTax) ||
  parsedTax < 0
) {
  errors.push('Invalid tax amount');
}

if (!employee) {
  errors.push('Employee is missing');
}

if (!Number.isFinite(parsedConfidence)) {
  errors.push('Invalid AI confidence');
}

// Match categories and payment methods without
// being affected by uppercase/lowercase differences.
const category =
  allowedCategories.find(
    function (value) {
      return value.toLowerCase() === asText(ai.category).toLowerCase();
    }
  ) || 'Other';

const paymentMethod =
  allowedPaymentMethods.find(
    function (value) {
      return value.toLowerCase() === asText(ai.payment_method).toLowerCase();
    }
  ) || 'Other';

// Keep output numbers valid.
// Invalid values are recorded in validation_errors.
const amount =
  Number.isFinite(parsedAmount) ? parsedAmount : 0;

const tax =
  Number.isFinite(parsedTax) ? parsedTax : 0;

const confidence =
  Number.isFinite(parsedConfidence)
    ? parsedConfidence
    : 0;

const validationStatus =
  errors.length === 0 ? 'Valid' : 'Invalid';

const exceedsLimit = amount > expenseLimit;

// Include execution and item identifiers to avoid
// duplicate IDs for items processed together.
const expenseId =
  'EXP-' + $execution.id + '-' + $runIndex + '-' + $itemIndex;

return {
  json: {
    expense_id: expenseId,
    employee: employee,
    vendor: vendor,
    receipt_date: receiptDate,
    amount: amount,
    tax: tax,
    currency: asText(ai.currency) || 'INR',
    category: category,
    payment_method: paymentMethod,
    receipt_number: asText(ai.receipt_number),
    description: asText(ai.description),
    ai_confidence: confidence,
    expense_limit: expenseLimit,
    exceeds_limit: exceedsLimit,
    approval_status: exceedsLimit
      ? 'Finance Review Required'
      : 'Within Limit',
    validation_status: validationStatus,
    validation_errors: errors.join('; '),
    processed_at: new Date().toISOString()
  }
};

