const items = $input.all();

// Read numbers safely.
// Supports numeric values and text such as "1,500.50" or "₹1,500.50".
// Missing or blank values use the supplied default.
function readNumber(value, defaultValue, fieldName, expenseId) {
  if (
    value === null ||
    value === undefined ||
    String(value).trim() === ''
  ) {
    return defaultValue;
  }

  let cleanedValue = value;

  if (typeof value === 'string') {
    cleanedValue = value
      .trim()
      .replace(/,/g, '')
      .replace(/[₹$€£]/g, '')
      .trim();
  }

  if (
    typeof cleanedValue !== 'number' &&
    typeof cleanedValue !== 'string'
  ) {
    throw new Error(
      'Invalid ' + fieldName + ' for expense ' + (expenseId || '(no Expense ID)')
    );
  }

  const number = Number(cleanedValue);

  if (cleanedValue === '' || !Number.isFinite(number)) {
    throw new Error(
      'Invalid ' + fieldName + ' for expense ' + (expenseId || '(no Expense ID)') + ': ' + String(value)
    );
  }

  return number;
}

function roundAmount(value) {
  return Number(value.toFixed(2));
}

let totalExpenses = 0;
let totalAmount = 0;
let totalTax = 0;
let overLimitCount = 0;

const categoryTotals = Object.create(null);
const employeeTotals = Object.create(null);

let highestExpense = null;

for (const item of items) {
  const expense = item.json;
  const expenseId = expense['Expense ID'] || '';

  // Use the same Google Sheet column names.
  const amount = readNumber(
    expense['Amount'],
    0,
    'Amount',
    expenseId
  );

  const tax = readNumber(
    expense['Tax'],
    0,
    'Tax',
    expenseId
  );

  const expenseLimit = readNumber(
    expense['Expense Limit'],
    5000,
    'Expense Limit',
    expenseId
  );

  const category = expense['Category'] || 'Other';
  const employee = expense['Employee'] || 'Unknown';

  const markedOverLimit =
    String(expense['Over Limit']).trim().toLowerCase() === 'true';

  const overLimit =
    markedOverLimit || amount > expenseLimit;

  totalExpenses++;
  totalAmount += amount;
  totalTax += tax;

  categoryTotals[category] =
    (categoryTotals[category] || 0) + amount;

  employeeTotals[employee] =
    (employeeTotals[employee] || 0) + amount;

  if (overLimit) {
    overLimitCount++;
  }

  if (
    highestExpense === null ||
    amount > highestExpense.amount
  ) {
    highestExpense = {
      expense_id: expenseId,
      vendor: expense['Vendor'] || '',
      employee: employee,
      amount: amount,
      currency: expense['Currency'] || ''
    };
  }
}

const averageExpense =
  totalExpenses > 0
    ? totalAmount / totalExpenses
    : 0;

// Keep the original behaviour:
// report month comes from the first item's Receipt Date.
let reportMonth = '';

if (items.length > 0 && items[0].json['Receipt Date']) {
  const receiptDate = new Date(
    items[0].json['Receipt Date']
  );

  if (!isNaN(receiptDate.getTime())) {
    reportMonth =
      receiptDate.toISOString().substring(0, 7);
  }
}

// Round category and employee totals.
for (const key of Object.keys(categoryTotals)) {
  categoryTotals[key] = roundAmount(categoryTotals[key]);
}

for (const key of Object.keys(employeeTotals)) {
  employeeTotals[key] = roundAmount(employeeTotals[key]);
}

// Return exactly the same output fields.
return [
  {
    json: {
      report_month: reportMonth,
      total_expenses: totalExpenses,
      total_amount: roundAmount(totalAmount),
      total_tax: roundAmount(totalTax),
      average_expense: roundAmount(averageExpense),
      over_limit_count: overLimitCount,
      category_totals: categoryTotals,
      employee_totals: employeeTotals,
      highest_expense: highestExpense
    }
  }
];
